set -x; uv run --no-project --python 3.13 python -c 'import re,sys,io
def rd(p):
    try: return io.open(p,encoding="utf-8").read()
    except OSError: sys.exit(3)
P="ios/BooksAndVocab/Views/Vocabulary/Scenes/ReviewCardView.swift"
E="ios/BooksAndVocab/Views/Vocabulary/Scenes/ReviewCardLayoutEditor.swift"
V="ios/BooksAndVocab/Views/Vocabulary/Scenes/ReviewCardLayoutPreviewCard.swift"
L="ios/BooksAndVocab/Views/Vocabulary/Scenes/ReviewCardLayout.swift"
M="ios/BooksAndVocab/Models/ReviewCardLayoutProfile.swift"
T="ios/BooksAndVocabTests/ReviewCardRenderPlanTests.swift"
p,e,v,l,m,t=rd(P),rd(E),rd(V),rd(L),rd(M),rd(T)
for x,s in ((p,"private func answerContent("),(p,"VocabTierLabel(tier: tier)"),(l,"struct ReviewCardRenderPlan"),(m,"case difficultyTier")):
    if s not in x: sys.exit(3)
def body(x,k):
    i=x.index(k); mm=re.compile(r"^    (?:@|private |func |// MARK)",re.M).search(x,i+len(k))
    return x[i:mm.start() if mm else len(x)]
ab=body(p,"private func answerContent(")
if "section: .core" not in ab: sys.exit(3)
def strip(x): return re.sub(r"/\*.*?\*/","",re.sub(r"//[^\n]*","",x),flags=re.S)
ec, vc, tc = strip(e), strip(v), strip(t)
if not re.search(r"back\.fields\s*==\s*\[\s*\.difficultyTier\s*,\s*\.graphLinks\s*,\s*\.example\s*,\s*\.explanation\s*,\s*\.collocations\s*\]",tc): sys.exit(3)
bound = re.search(r"back\.aboveCore\s*==\s*\[\s*(?:ReviewCardField)?\.difficultyTier\s*\]",tc) is not None
render_side = bound and "aboveCore" in l and "aboveCore" in ab and ab.index("aboveCore") < ab.index("section: .core")
# 編輯器不得再維護第二份欄位排序（previewSection / previewRow 是它的兩個名字），
# 且預覽必須經 ReviewCardLayoutPreviewCard 走到同一支 renderer。
no_second_ordering = ("previewSection" not in ec) and ("previewRow(" not in ec)
editor_shows_real_card = "ReviewCardLayoutPreviewCard(" in ec and "ReviewCardView(" in vc
sys.exit(0 if (render_side and no_second_ordering and editor_shows_real_card) else 1)'
